export const PRIVACY_POLICY_HTML: string = "<h1>Pool — Privacy Policy</h1>\n<p><strong>Effective date:</strong> 12 September 2026\n<strong>Last updated:</strong> 12 September 2026</p>\n<hr>\n<h2>1. Who we are</h2>\n<p>Pool (&quot;<strong>Pool</strong>&quot;, &quot;<strong>we</strong>&quot;, &quot;<strong>us</strong>&quot;) is operated by <strong>Pool Labs LLC</strong>, a Missouri limited liability company based in St. Louis, Missouri, USA.</p>\n<p>Pool is a group-spending app: friends put equal amounts into a shared pool, spend from the shared balance, and settle any leftover directly with one another. <strong>Pool is not a bank and does not hold, transmit or move money.</strong> See §5.</p>\n<p>Privacy contact: <strong><a href=\"mailto:support@poolapp.co\">support@poolapp.co</a></strong></p>\n<hr>\n<h2>2. What this policy covers</h2>\n<p>This policy applies to:</p>\n<ul>\n<li>the <strong>Pool mobile app</strong> for iOS and Android (including staging/TestFlight/beta builds);</li>\n<li>the <strong>poolapp.co website</strong>, including the waitlist and marketing pages;</li>\n<li><strong>emails and support conversations</strong> you have with us;</li>\n<li>the <strong>Pool admin dashboard</strong>, an internal tool used only by Pool staff (described so you know what staff can see — §9).</li>\n</ul>\n<p>It does not cover third-party apps you use to actually send money (Venmo, Cash App, PayPal, Zelle, Interac e-Transfer). Those are governed by their own terms and privacy policies.</p>\n<hr>\n<h2>3. Information we collect</h2>\n<h3>3.1 Information you give us</h3>\n<table>\n<thead>\n<tr>\n<th>Category</th>\n<th>What</th>\n<th>Required?</th>\n<th>Why</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>Account</strong></td>\n<td>Email address; optional password (stored only as a salted hash); username; first/last or display name; profile photo</td>\n<td>Email, username and date of birth are required</td>\n<td>Sign-in, identifying you to the people you share pools with</td>\n</tr>\n<tr>\n<td><strong>Age</strong></td>\n<td>Date of birth</td>\n<td>Required</td>\n<td>Pool is <strong>18+</strong>. We store your date of birth to enforce this. Other users only ever see a derived whole-year age, and only if you opt into Discover</td>\n</tr>\n<tr>\n<td><strong>Social sign-in</strong></td>\n<td>If you sign in with Apple or Google: the provider&#39;s stable account identifier and the email the provider gives us at link time</td>\n<td>Optional</td>\n<td>Signing you in without a password. We do not receive your Apple/Google password or contacts</td>\n</tr>\n<tr>\n<td><strong>Discover profile</strong></td>\n<td>Bio, interests, what you do (occupation), lifestyle, gender (male / female / prefer not to say), city, a &quot;make me discoverable&quot; switch</td>\n<td>Optional, all off by default</td>\n<td>Helping you find people and pools with similar interests. Nothing here is visible to strangers unless you turn discoverability on</td>\n</tr>\n<tr>\n<td><strong>Payment handles</strong></td>\n<td>Your Venmo, Cash App, PayPal, Zelle and/or Interac handle, and a preferred one</td>\n<td>Optional</td>\n<td>So pool members can pay you back. You must explicitly confirm each handle exactly as it will be stored. <strong>These are visible to members of your pools</strong> — see §5</td>\n</tr>\n<tr>\n<td><strong>Pool data</strong></td>\n<td>Pool names, descriptions, category, tags, house rules, cover image, visibility (private/public), member list and roles</td>\n<td>Required to use a pool</td>\n<td>Running the pool</td>\n</tr>\n<tr>\n<td><strong>Spending data</strong></td>\n<td>Amounts you deposit (currently simulated — §5), expenses you log (amount, description/merchant, date, who paid, how it is split, line items), settlements you record (&quot;I paid&quot; / &quot;I received&quot;) and how (e.g. &quot;Venmo&quot;)</td>\n<td>Required to log an expense</td>\n<td>Keeping the shared ledger and showing each member what they owe or are owed</td>\n</tr>\n<tr>\n<td><strong>Receipt scans</strong></td>\n<td>A photo of a receipt, if you choose to scan one</td>\n<td>Optional</td>\n<td>Auto-filling amount and line items. <strong>The image is deleted immediately after parsing</strong> — see §7</td>\n</tr>\n<tr>\n<td><strong>Messages</strong></td>\n<td>Direct messages, pool chats, group chats, message requests, requests to join a pool (with an optional note), messages to the pool&#39;s admins</td>\n<td>Optional</td>\n<td>In-app messaging</td>\n</tr>\n<tr>\n<td><strong>Safety actions</strong></td>\n<td>Accounts you block or mute; reports you file (we keep a snapshot of the reported content as evidence)</td>\n<td>Optional</td>\n<td>Keeping you safe; store-policy compliance</td>\n</tr>\n<tr>\n<td><strong>Support</strong></td>\n<td>Messages you send to &quot;Pool Support&quot; in the app</td>\n<td>Optional</td>\n<td>Answering you</td>\n</tr>\n<tr>\n<td><strong>Waitlist (website)</strong></td>\n<td>First and last name, email address, country, and optionally your answers to a short questionnaire</td>\n<td>Optional</td>\n<td>Telling you when Pool is available</td>\n</tr>\n</tbody></table>\n<h3>3.2 Information collected automatically</h3>\n<table>\n<thead>\n<tr>\n<th>Category</th>\n<th>What</th>\n<th>Why</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>Device &amp; app</strong></td>\n<td>Device model and OS version, app version and build, a per-install identifier, language, time zone</td>\n<td>Making the app work, deciding whether your build needs an update, diagnosing problems</td>\n</tr>\n<tr>\n<td><strong>Push tokens</strong></td>\n<td>The Apple/Google/Expo push token for your device, if you allow notifications</td>\n<td>Delivering notifications. It is a routing address, not a credential, and is revoked when you sign out or turn notifications off</td>\n</tr>\n<tr>\n<td><strong>Trusted device</strong></td>\n<td>A random device token, if you choose &quot;Remember this device&quot;</td>\n<td>Letting you skip the email code next time. You can forget a device from Profile → <em>This device</em> or <em>Account security</em></td>\n</tr>\n<tr>\n<td><strong>Location</strong></td>\n<td>If you turn location on: your approximate coordinates, resolved to a <strong>city</strong>. Only the <strong>city</strong> is ever shown to anyone else</td>\n<td>Finding pools and people near you. We never show another user your coordinates or a distance finer than &quot;nearby / in your area&quot;</td>\n</tr>\n<tr>\n<td><strong>Usage analytics</strong></td>\n<td>Screen views and product actions (e.g. &quot;pool created&quot;, &quot;expense logged&quot;, &quot;help opened&quot;) with a session id</td>\n<td>Understanding which features are used. <strong>We strip amounts, coordinates, names, emails and free text before storing these</strong> — enforced on the server, not trusted to the app</td>\n</tr>\n<tr>\n<td><strong>Server logs</strong></td>\n<td>IP address, request path, timing, a request id, and your user id if signed in; which operation you were attempting and whether it was refused</td>\n<td>Security, abuse prevention, rate limiting, debugging</td>\n</tr>\n<tr>\n<td><strong>Crash reports</strong></td>\n<td>Stack traces, device/OS, app version, your user id, and the sequence of screens before a crash</td>\n<td>Fixing crashes. Sent to Sentry (§6)</td>\n</tr>\n<tr>\n<td><strong>Audit trail</strong></td>\n<td>For financial and governance actions (deposits, expenses, settlements, role changes, invitations, account deletion, password changes, admin actions): who did what, when, and the amounts involved</td>\n<td>An immutable record we can use to answer &quot;what happened to my money/pool&quot; and to investigate misuse — see §7 for its special retention</td>\n</tr>\n<tr>\n<td><strong>Website</strong></td>\n<td>Standard web-server logs and privacy-focused, cookieless page analytics (Vercel Analytics — the site&#39;s only analytics; no advertising pixels)</td>\n<td>Understanding site traffic</td>\n</tr>\n</tbody></table>\n<h3>3.3 What we do <strong>not</strong> collect</h3>\n<ul>\n<li><strong>Bank account numbers, card numbers or card details.</strong> Pool never asks for them. The &quot;card&quot; shown in the app&#39;s wallet feature is a demo card number generated by Pool that cannot be charged (§5).</li>\n<li><strong>Your contacts.</strong> Pool does not read your address book.</li>\n<li><strong>Precise location history.</strong> We keep your latest approximate coordinates only while location sharing is on; turning it off clears them.</li>\n<li><strong>Data from anyone under 18.</strong> See §11.</li>\n<li><strong>Advertising identifiers</strong> (IDFA/GAID). Pool contains no advertising SDKs.</li>\n</ul>\n<hr>\n<h2>4. How we use information</h2>\n<table>\n<thead>\n<tr>\n<th>Purpose</th>\n<th>Examples</th>\n<th>Legal basis (where required)</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Providing the service</td>\n<td>Sign-in, pools, ledger, splits, settlements, notifications, messaging</td>\n<td>Performance of our contract with you</td>\n</tr>\n<tr>\n<td>Discover &amp; matching</td>\n<td>Ranking people/pools by shared interests, occupation, and city; optional AI ranking (§4.1)</td>\n<td>Consent — only if you turn on discoverability</td>\n</tr>\n<tr>\n<td>Safety &amp; integrity</td>\n<td>Blocking, reports, content moderation of pool names, rate limiting, fraud/abuse detection</td>\n<td>Legitimate interests; legal obligation (app-store safety requirements)</td>\n</tr>\n<tr>\n<td>Communications</td>\n<td>Sign-in codes; transactional emails; push notifications about pools, money you owe, friend requests and messages; optional discovery suggestions</td>\n<td>Contract; consent for optional categories (§10)</td>\n</tr>\n<tr>\n<td>Product improvement</td>\n<td>Aggregate usage analytics, crash reports</td>\n<td>Legitimate interests</td>\n</tr>\n<tr>\n<td>Support</td>\n<td>Reading and replying to your support thread</td>\n<td>Contract</td>\n</tr>\n<tr>\n<td>Legal</td>\n<td>Keeping financial/audit records; responding to lawful requests; enforcing our Terms</td>\n<td>Legal obligation; legitimate interests</td>\n</tr>\n</tbody></table>\n<p><strong>We do not sell your personal information. We do not share it for targeted advertising. We do not show ads.</strong></p>\n<h3>4.1 Automated ranking and AI</h3>\n<p>If you turn on discoverability, Pool may use an AI model (Amazon Bedrock — Anthropic Claude and Amazon Titan, running inside our own AWS account) to summarize your <strong>bio, interests, occupation and an age bracket</strong> into tags and a numerical &quot;embedding&quot; used only to rank Discover results. This input never includes your name, email, exact age or date of birth, location coordinates, messages or any money data. Results are used only for ordering suggestions; <strong>no automated decision with legal or similarly significant effect is made about you.</strong> If the AI service is unavailable, Pool falls back to simple keyword matching.</p>\n<p>Pool also runs an automated word list over <strong>pool names, descriptions, tags and house rules</strong> to block slurs and profanity. It produces false positives; it never blocks your account on its own.</p>\n<hr>\n<h2>5. Money, payment handles and what other users can see</h2>\n<p><strong>Pool does not hold, transmit or move money.</strong> In the current release, deposits and balances are a <strong>simulated ledger</strong> used to track what each person put in and spent; no card is charged and no funds are held. When members settle up, the payment happens <strong>outside Pool</strong> — in Venmo, Cash App, PayPal, Zelle, Interac or by hand — and Pool only records that a payment was reported.</p>\n<p>Because settling up means sending real money to whatever handle you stored, <strong>payment handles are treated as published routing information</strong>:</p>\n<ul>\n<li>Handles are shown, verbatim, to <strong>members of the pools you are in</strong>, on the settle-up screen and on your pool profile.</li>\n<li>Handles are shown to <strong>no one else</strong> — not to strangers in Discover, not on public pool member lists, not on leaderboards.</li>\n<li>Before we store a handle, the app shows you the exact string that will be saved and asks you to confirm it. <strong>You are responsible for its accuracy</strong> (see Terms of Service).</li>\n</ul>\n<p><strong>What members of your pools can see:</strong> your name, username, photo, role, your share of each expense, your balance in the pool, settlements you are party to, and the handles above.</p>\n<p><strong>What anyone signed in can see, if a pool is PUBLIC:</strong> the pool&#39;s name, description, category/tags, house rules, city (or exact venue if the pool&#39;s creator opted in), member count, the display names/photos/roles of its members, and — if the pool has not opted out — its position on global leaderboards, which for the top few pools includes the pool&#39;s total spend for a period (never per-person amounts). Private pools are visible only to their members.</p>\n<p><strong>What other users can see about you if you turn on discoverability:</strong> display name, username, photo, bio, interests, occupation, lifestyle, city, gender (if set) and age (whole years). Never your email, date of birth, coordinates, handles or money.</p>\n<p><strong>If discoverability is off</strong>, you do not appear in Discover, suggestions, nearby results, public pool member lists by handle, or leaderboards. People who already know your username can still send you a friend request or a pool invite.</p>\n<hr>\n<h2>6. Who we share information with</h2>\n<p>We share personal information only with service providers acting on our instructions, and only what each needs:</p>\n<table>\n<thead>\n<tr>\n<th>Provider</th>\n<th>What</th>\n<th>Why</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>Amazon Web Services</strong> (US regions)</td>\n<td>All app data: database, file storage, logs, email sending (SES), AI (Bedrock), receipt OCR (Textract), map tiles (CloudFront)</td>\n<td>Hosting Pool</td>\n</tr>\n<tr>\n<td><strong>Expo (EAS)</strong></td>\n<td>Push token routing; app update delivery</td>\n<td>Notifications; over-the-air updates</td>\n</tr>\n<tr>\n<td><strong>Apple (APNs, Sign in with Apple, App Store, Wallet)</strong> and <strong>Google (FCM, Google Sign-In, Play, Wallet)</strong></td>\n<td>Push delivery; sign-in identity; the demo card pass if you add it to your wallet</td>\n<td>Platform services</td>\n</tr>\n<tr>\n<td><strong>Sentry</strong></td>\n<td>Crash reports and error diagnostics (may include your user id and the screens you visited; never message bodies, amounts or handles by design)</td>\n<td>Crash reporting</td>\n</tr>\n<tr>\n<td><strong>OpenStreetMap / Nominatim</strong></td>\n<td>The text of a city or place search you type in the city picker or map search</td>\n<td>Geocoding. We send your query and a Pool user-agent, never your identity. Map tiles themselves are served from our own CDN</td>\n</tr>\n<tr>\n<td><strong>Vercel</strong></td>\n<td>Website hosting and cookieless page analytics; the admin dashboard</td>\n<td>Website / internal tools</td>\n</tr>\n<tr>\n<td><strong>Google Firebase</strong></td>\n<td>Website waitlist storage and staff sign-in for the marketing site</td>\n<td>Website</td>\n</tr>\n<tr>\n<td><strong>Mailtrap</strong></td>\n<td>Test-inbox for <strong>staging builds only</strong> — never production email</td>\n<td>Testing</td>\n</tr>\n</tbody></table>\n<p>We may also disclose information: to comply with law or a valid legal request; to enforce our Terms; to protect the rights, safety or property of Pool, our users or others; or as part of a merger, acquisition or sale of assets (with notice to you).</p>\n<p><strong>We do not sell personal information and have not done so in the preceding 12 months.</strong></p>\n<hr>\n<h2>7. How long we keep information</h2>\n<table>\n<thead>\n<tr>\n<th>Data</th>\n<th>Retention</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Account &amp; profile</td>\n<td>Until you delete your account (§8)</td>\n</tr>\n<tr>\n<td>Pool, expense and settlement records</td>\n<td>For the life of the pool; anonymized (not deleted) when you delete your account, so other members&#39; ledgers still add up</td>\n</tr>\n<tr>\n<td>Messages</td>\n<td>Until you delete your account, at which point <strong>your messages are hard-deleted</strong>; a group chat whose last member leaves is deleted</td>\n</tr>\n<tr>\n<td>Receipt images</td>\n<td><strong>Deleted immediately after parsing</strong> (success or failure); a storage rule deletes any stragglers within <strong>3 days</strong>. Only the extracted amounts persist</td>\n</tr>\n<tr>\n<td>Precise coordinates</td>\n<td>Latest fix only; cleared when you turn location sharing off</td>\n</tr>\n<tr>\n<td>Push and trusted-device tokens</td>\n<td>Until you sign out, revoke, or turn notifications off</td>\n</tr>\n<tr>\n<td>Usage analytics</td>\n<td><strong>12 months</strong>, then automatically purged</td>\n</tr>\n<tr>\n<td>Server &amp; crash logs</td>\n<td>Server logs: <strong>30 days</strong>. Crash reports: <strong>90 days</strong> (Sentry&#39;s standard retention)</td>\n</tr>\n<tr>\n<td><strong>Audit trail</strong></td>\n<td><strong>24 months</strong>, then automatically purged. The audit trail is append-only and cannot be edited or deleted early, by us or by anyone. It records the actor, amounts and — for payment-handle changes — the handle value, <strong>and survives account deletion</strong> (the actor id is kept; the account behind it is anonymized)</td>\n</tr>\n<tr>\n<td>Safety reports</td>\n<td>Retained with their content snapshot for as long as needed to act on them and to demonstrate action to app-store reviewers</td>\n</tr>\n<tr>\n<td>Waitlist</td>\n<td>Until launch communications are complete or you ask us to remove you</td>\n</tr>\n</tbody></table>\n<hr>\n<h2>8. Your choices and rights</h2>\n<p><strong>In the app, at any time:</strong></p>\n<ul>\n<li><strong>Edit</strong> your profile, interests, city, gender, handles (Profile).</li>\n<li><strong>Turn discoverability off</strong> (Profile → Discover settings) — you disappear from Discover immediately.</li>\n<li><strong>Turn location off</strong> — coordinates are cleared.</li>\n<li><strong>Control notifications</strong> per category, including the optional &quot;discovery suggestions&quot; category (Profile → Notifications), or at the OS level.</li>\n<li><strong>Block, mute or report</strong> any user or message. Blocking is never disclosed to the other person.</li>\n<li><strong>Forget a trusted device</strong> or <strong>sign out of every other device</strong> (Profile → Account security).</li>\n<li><strong>Delete your account</strong> (Profile → Delete account). This removes your email, name, photo, date of birth, handles, social sign-in links, push tokens and devices; hard-deletes your messages; and anonymizes your ledger history and audit-trail entries as described in §7. Deletion is immediate and cannot be undone.</li>\n</ul>\n<p><strong>By email to <a href=\"mailto:support@poolapp.co\">support@poolapp.co</a>:</strong> request a copy of the personal information we hold about you, correction of anything you cannot edit in-app, deletion if you cannot access the app, or to opt out of the waitlist. We will verify your request against the email on the account and respond within <strong>30 days</strong> (45 days where a law allows and we tell you why).</p>\n<p><strong>Residents of California and other US states with privacy laws</strong> have the right to know, access, correct and delete personal information, to opt out of &quot;sale&quot; or &quot;sharing&quot; (we do neither), and not to be discriminated against for exercising these rights. You may use an authorized agent; we will ask the agent for proof of authorization. We honour these rights for all US users whether or not a given state law technically applies to Pool at its current size.</p>\n<p><strong>If you are in the EU/UK:</strong> Pool is a US service and does not target the EU/UK. If we process your data anyway, you have the rights under the GDPR/UK GDPR to access, rectify, erase, restrict, port and object, and to lodge a complaint with your supervisory authority.</p>\n<hr>\n<h2>9. What Pool staff can see</h2>\n<p>A small number of Pool staff (&quot;platform admins&quot;) can, through an internal dashboard:</p>\n<ul>\n<li>view usage metrics and funnels (aggregate; no amounts, no message content);</li>\n<li>view a pool&#39;s ledger, including amounts, to investigate a balance problem, and record a correcting adjustment — <strong>every view and every adjustment is written to the audit trail</strong>;</li>\n<li>view a specific user&#39;s log timeline to answer a support request — <strong>each lookup is itself audited</strong>;</li>\n<li>review safety reports and, where warranted, remove a message or suspend an account;</li>\n<li>temporarily <strong>&quot;view as&quot;</strong> a user in <strong>read-only</strong> mode for up to 15 minutes, only with a written reason, with every session audited under the staff member&#39;s own identity.</li>\n</ul>\n<p>Staff cannot read your password (we don&#39;t have it), cannot send messages as you, and cannot make writes while viewing as you. Admin access is granted and revoked individually and every grant/revocation is audited.</p>\n<hr>\n<h2>10. Notifications and emails</h2>\n<ul>\n<li><strong>Sign-in codes and security emails</strong> are sent whenever you ask to sign in; they cannot be turned off while you have an account.</li>\n<li><strong>Transactional push notifications</strong> (pool invites, expenses logged in your pools, money you owe, friend requests, messages) are on by default and can be turned off per category.</li>\n<li><strong>Settle-up reminders</strong> are sent at most once per debt per week and once per person per week.</li>\n<li><strong>Discovery suggestions</strong> (&quot;someone near you shares your interests&quot;) are on by default and can be turned off. They never contain the other person&#39;s name, photo or details on your lock screen.</li>\n<li><strong>Profile-completion nudges</strong> are limited to three per topic, ever.</li>\n<li><strong>No push notification ever contains an amount, a balance, a message body, an email address or a location.</strong> By design, the lock-screen copy is separate from the in-app copy.</li>\n</ul>\n<p>We do not send marketing email. If we ever introduce a newsletter it will be opt-in with an unsubscribe link.</p>\n<hr>\n<h2>11. Children</h2>\n<p>Pool is for adults. You must be <strong>18 or older</strong> to create an account; we check your date of birth at signup and refuse under-age dates. We do not knowingly collect information from anyone under 18. If you believe a minor has an account, email <a href=\"mailto:support@poolapp.co\">support@poolapp.co</a> and we will delete it.</p>\n<hr>\n<h2>12. Security</h2>\n<p>We protect your information with, among other measures: TLS for all traffic; encryption of data at rest in AWS (database and file storage); passwords stored only as salted hashes; short-lived sign-in codes with attempt limits; the ability to revoke all other sessions; per-account and per-IP rate limits; secrets redaction in logs; an append-only, tamper-evident audit trail; least-privilege infrastructure roles; and identity-gated, audited administrative access. No system is perfectly secure; if we learn of a breach affecting your information we will notify you as required by law.</p>\n<hr>\n<h2>13. International transfers</h2>\n<p>Pool is hosted in the United States. If you use Pool from outside the US, your information is transferred to and processed in the US.</p>\n<hr>\n<h2>14. Beta, staging and test builds</h2>\n<p>If you are using a TestFlight, Play internal-testing or &quot;Pool (Staging)&quot; build, the app is clearly labelled and the same rules apply, with two differences: staging data may be <strong>wiped and reseeded</strong> at any time, and staging emails are delivered to a Mailtrap test inbox rather than sent externally. Do not put real financial information into a staging build.</p>\n<hr>\n<h2>15. Changes to this policy</h2>\n<p>We will post any changes here and update the &quot;Last updated&quot; date. For material changes we will notify you in the app or by email before they take effect. Continued use after the effective date means you accept the updated policy.</p>\n<hr>\n<h2>16. Contact</h2>\n<p>Pool Labs LLC · St. Louis, Missouri\n<strong><a href=\"mailto:support@poolapp.co\">support@poolapp.co</a></strong></p>\n";
